def utc_now_iso() -> str:
    return datetime.now(timezone.utc).astimezone().isoformat()


def normalize_text(value: str) -> str:
    normalized = unicodedata.normalize("NFKD", value or "")
    normalized = "".join(ch for ch in normalized if not unicodedata.combining(ch))
    normalized = normalized.lower()
    normalized = re.sub(r"\s+", " ", normalized).strip()
    return normalized


def slugify_words(value: str) -> str:
    normalized = normalize_text(value)
    normalized = re.sub(r"[^a-z0-9]+", "-", normalized)
    return normalized.strip("-")


def relative_display(path: Path, root: Path) -> str:
    try:
        rel = path.resolve().relative_to(root.resolve())
    except ValueError:
        rel = path.resolve()
    value = str(rel).replace("/", "\\")
    return value if value else "."


def is_operational_segment(name: str) -> bool:
    return name in OPERATIONAL_EXCLUDES


def is_hidden_obsidian_config(path: Path) -> bool:
    return path.is_dir() and path.name == ".obsidian"


def list_subvault_roots(root: Path) -> list[Path]:
    roots: list[Path] = []
    if (root / ".obsidian").is_dir():
        roots.append(root.resolve())
    for current_root, dirs, _ in os.walk(root):
        current = Path(current_root)
        dirs[:] = [
            item
            for item in dirs
            if not is_operational_segment(item) and not (current == root and item == ".obsidian")
        ]
        if ".obsidian" in dirs:
            roots.append((current).resolve())
            dirs.remove(".obsidian")
    unique = sorted({item for item in roots}, key=lambda item: len(item.parts))
    return unique


def owning_subvault(path: Path, subvault_roots: list[Path]) -> Path | None:
    resolved = path.resolve()
    matches = [root for root in subvault_roots if resolved.is_relative_to(root)]
    if not matches:
        return None
    return max(matches, key=lambda item: len(item.parts))


def is_nested_subvault_path(path: Path, root: Path, subvault_roots: list[Path]) -> bool:
    owner = owning_subvault(path, subvault_roots)
    return owner is not None and owner != root.resolve()


def scan_files(root: Path, include_operational: bool = False) -> tuple[list[FileRecord], list[Path]]:
    root = root.resolve()
    subvault_roots = list_subvault_roots(root)
    records: list[FileRecord] = []
    for current_root, dirs, files in os.walk(root):
        current = Path(current_root)
        if not include_operational:
            dirs[:] = [item for item in dirs if not is_operational_segment(item)]
        dirs[:] = [item for item in dirs if item != ".obsidian"]
        for filename in files:
            path = current / filename
            if not include_operational:
                try:
                    rel_parts = path.resolve().relative_to(root).parts
                except ValueError:
                    continue
                if any(is_operational_segment(part) for part in rel_parts):
                    continue
            stat = path.stat()
            top_level_area = path.resolve().relative_to(root).parts[0] if path.resolve() != root else "."
            records.append(
                FileRecord(
                    path=path.resolve(),
                    relative_path=relative_display(path, root),
                    extension=path.suffix.lower() or "[no extension]",
                    size=stat.st_size,
                    modified_at=datetime.fromtimestamp(stat.st_mtime).astimezone().isoformat(),
                    created_at=datetime.fromtimestamp(stat.st_ctime).astimezone().isoformat(),
                    top_level_area=top_level_area,
                    in_nested_subvault=is_nested_subvault_path(path, root, subvault_roots),
                )
            )
    records.sort(key=lambda item: item.relative_path.lower())
    return records, subvault_roots


def read_text(path: Path) -> str:
    for encoding in ("utf-8", "utf-8-sig", "cp1252", "latin-1"):
        try:
            return path.read_text(encoding=encoding)
        except UnicodeDecodeError:
            continue
    return path.read_text(encoding="utf-8", errors="ignore")


def sha256_for_path(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def token_words(text: str) -> list[str]:
    return re.findall(r"[0-9a-zA-ZÃ€-Ã¿_]{2,}", normalize_text(text))


def token_ngrams(words: list[str], size: int = 3) -> set[str]:
    if len(words) < size:
        return set(words)
    return {" ".join(words[index : index + size]) for index in range(0, len(words) - size + 1)}


def excerpt_sentences(text: str, limit: int = 8) -> list[str]:
    parts = re.split(r"(?<=[.!?])\s+|\n{2,}", text)
    cleaned = []
    for part in parts:
        item = re.sub(r"\s+", " ", part.strip())
        if len(item.split()) >= 3:
            cleaned.append(item)
        if len(cleaned) >= limit:
            break
    return cleaned


def parse_links(text: str) -> tuple[list[str], list[str]]:
    wiki = [match.group(1).strip() for match in WIKILINK_RE.finditer(text)]
    markdown = [match.group(1).strip() for match in MARKDOWN_LINK_RE.finditer(text)]
    return wiki, markdown


def strip_frontmatter(text: str) -> str:
    if not text.startswith("---\n"):
        return text
    marker = "\n---\n"
    closing = text.find(marker, 4)
    if closing == -1:
        return text
    return text[closing + len(marker) :]


def is_generic_name(stem: str) -> bool:
    normalized = normalize_text(stem)
    return not normalized or any(re.match(pattern, normalized) for pattern in GENERIC_NAME_PATTERNS)
